CSS = '''
:root{--ink:#17302f;--muted:#536662;--paper:#f6f4ed;--white:#fffefa;--line:#d8dfd6;--green:#116c5d;--gold:#b46d24;--nav:270px}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:30px}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.75 system-ui,-apple-system,"Segoe UI",sans-serif}a{color:var(--green);text-underline-offset:3px}a:hover{color:#94450f}nav{position:fixed;inset:0 auto 0 0;width:var(--nav);background:#153b36;color:#e7f0e9;padding:28px 21px;overflow:auto}nav .brand{font-size:12px;text-transform:uppercase;letter-spacing:2px;color:#a5cdc0}nav h2{font:600 25px/1.25 Georgia,serif;margin:12px 0 24px}nav a{display:block;color:#dbe6df;text-decoration:none;font-size:13px;line-height:1.4;padding:9px 10px;border-left:2px solid transparent}nav a:hover,nav a.active{background:#244e45;border-color:#dfb873;color:white}nav .tools{margin-top:24px;display:flex;gap:8px;flex-wrap:wrap}button{font:inherit;cursor:pointer;border:1px solid #8fa99c;border-radius:5px;background:transparent;color:inherit;padding:7px 11px;font-size:12px}.skip{position:absolute;top:-100px;left:10px;background:white;padding:10px;z-index:5}.skip:focus{top:10px}main{margin-left:var(--nav);max-width:1450px}header{background:#e6ede3;padding:65px 7% 54px;border-bottom:1px solid var(--line)}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:var(--green);font-weight:700}h1{font:500 clamp(36px,4.4vw,65px)/1.1 Georgia,serif;max-width:900px;margin:22px 0;color:#153b36}header .subtitle{font-size:21px;max-width:780px;line-height:1.5}header .meta{font-size:13px;color:var(--muted);margin-top:25px}.hero-line{width:80px;height:4px;background:var(--gold);margin:25px 0}section{padding:52px 7%;border-bottom:1px solid var(--line);background:var(--white)}section:nth-child(even){background:#f8f8f1}h2{font:500 clamp(27px,3vw,38px)/1.2 Georgia,serif;margin:13px 0 28px}h3{font-size:21px;line-height:1.35;margin:34px 0 14px}h4{margin:0 0 8px;font-size:19px}p{margin:14px 0;max-width:1050px}.lead{font-size:23px;line-height:1.55;color:#215447}.table-wrap{overflow:auto;margin:22px 0;border:1px solid var(--line);border-radius:5px}table{border-collapse:collapse;width:100%;font-size:14px;line-height:1.55}th{text-align:left;background:#e5ece3;font-weight:700;padding:13px;vertical-align:top}td{padding:13px;vertical-align:top;border-top:1px solid var(--line);min-width:140px}td:first-child{font-weight:600}tr:nth-child(even){background:#f3f5ef}code{font:0.86em/1.6 Consolas,monospace;overflow-wrap:anywhere;color:#375e58}.equation{border-left:3px solid #b18a4b;background:#f1eee2;padding:20px 24px;margin:23px 0;font:17px/1.9 "Cambria Math",Georgia,serif;overflow:auto}.note,.warning,.verdict{padding:22px 25px;border-left:4px solid var(--green);background:#eaf1e9;margin:25px 0}.warning{background:#faf0dd;border-color:#b97825}.verdict{background:#173e36;color:#f1f6ef;border-color:#d2a558}.note p,.warning p,.verdict p{margin-bottom:0}.flow{display:flex;gap:12px;align-items:center;margin:28px 0;flex-wrap:wrap}.flow span{background:#e6eee5;border:1px solid #cad8c9;border-radius:5px;padding:15px;flex:1;min-width:150px;font-weight:600;line-height:1.4;font-size:15px}.legend{font-size:13px;line-height:2.6;margin:20px 0}.tag{font-size:10px;letter-spacing:.7px;background:#dbe9df;padding:5px 8px;border-radius:4px;font-weight:700;margin-right:5px}.theory{background:#e3e7f2}.assumption{background:#f6e5cb}.pending{background:#eee0ed}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0}.stats div{padding:20px;background:#e5eee3;border-top:3px solid #357c67}.stats strong{display:block;font:36px/1.2 Georgia,serif}.stats span{display:block;font-size:12px;margin-top:10px}.calculator{border:1px solid #a5bcaa;padding:25px;background:#edf4ea;margin:30px 0}.calculator p{font-size:14px}.calculator label{display:inline-block;font-size:13px;margin:8px 20px 12px 0}.calculator input,.calculator select{display:block;width:160px;margin-top:6px;border:1px solid #8aa494;border-radius:4px;background:white;padding:9px;font:16px system-ui;color:var(--ink)}output{display:block;padding:18px;background:#dbe9d7;margin-top:10px;font-weight:700}.closing{font:24px/1.6 Georgia,serif;border-top:1px solid var(--line);padding-top:25px}li{margin:8px 0}footer{padding:25px 7%;font-size:13px;color:var(--muted)}.progress{position:fixed;top:0;left:var(--nav);height:3px;background:#b78942;z-index:4;width:0}.compact section p,.compact section li{line-height:1.55}.compact section{padding-top:32px;padding-bottom:32px}:focus-visible{outline:3px solid #bd7c28;outline-offset:4px}@media(max-width:1050px){:root{--nav:225px}nav{padding:22px 12px}body{font-size:16px}section,header{padding-left:5%;padding-right:5%}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:740px){nav{position:relative;width:auto;max-height:none;padding:22px}nav h2{margin-bottom:12px}nav .links{display:flex;gap:5px;flex-wrap:wrap}nav a{font-size:12px;background:#214c43;border-radius:4px;padding:7px}nav .tools{margin-top:15px}main{margin-left:0}header{padding-top:40px}.progress{left:0}.flow b{display:none}td{min-width:160px}section{padding:35px 6%}h1{font-size:40px}.lead{font-size:20px}}@media print{@page{size:A4;margin:17mm}body{background:white;font-size:10pt;line-height:1.5}nav,.progress,.skip,.calculator{display:none}main{margin:0;max-width:none}header{padding:15px 0 25px;background:white}h1{font-size:32pt}section{padding:20px 0;background:white!important;break-before:page}h2{font-size:22pt}h3{font-size:14pt;break-after:avoid}table{font-size:8.5pt}.table-wrap{overflow:visible}tr{break-inside:avoid}td{min-width:0}a{color:inherit}p{orphans:3;widows:3}.equation,.note,.warning,.verdict{break-inside:avoid}.verdict{color:var(--ink);background:#eef1e9}.stats strong{font-size:25pt}footer{padding:20px 0}}
'''
JS = '''
const fmt=(v,n=1)=>v.toLocaleString('es-PE',{maximumFractionDigits:n,minimumFractionDigits:n});
function calc(){const th=Number(document.querySelector('#calc-order').value),cut=Number(document.querySelector('#calc-cut').value),inv=Number(document.querySelector('#calc-inv').value);const out=document.querySelector('#calc-result');if(!Number.isFinite(cut)||!Number.isFinite(inv)||cut<0||cut>3||inv<100||inv>50000){out.textContent='Usa recorte entre 0 y 3 e inventario entre 100 y 50.000 kg. Son límites ilustrativos, no operativos.';return}const feo=-th*cut*inv;out.textContent=`${fmt(feo)} kg FeO · ${fmt(.43*feo)} kg Sn a dross evitados · +${fmt(.0028*feo,3)} pp KPI (estimaciones)`;}
document.querySelectorAll('.calculator input,.calculator select').forEach(e=>e.addEventListener('input',calc));calc();
document.querySelector('#print').addEventListener('click',()=>window.print());document.querySelector('#density').addEventListener('click',function(){document.body.classList.toggle('compact');this.setAttribute('aria-pressed',document.body.classList.contains('compact'));});
const links=[...document.querySelectorAll('nav .links a')];const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){links.forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id));}})},{rootMargin:'-10% 0px -65% 0px'});document.querySelectorAll('section').forEach(s=>observer.observe(s));
window.addEventListener('scroll',()=>{const denom=document.documentElement.scrollHeight-innerHeight;document.querySelector('.progress').style.width=(denom>0?scrollY/denom*100:0)+'%';},{passive:true});
'''

nav=''.join(f'<a href="#{id}">{escape(eyebrow)}</a>' for id,eyebrow,title,body in sections)
body=''.join(f'<section id="{id}" aria-labelledby="h-{id}"><div class="eyebrow">{escape(eyebrow)}</div><h2 id="h-{id}">{escape(title)}</h2>{content}</section>' for id,eyebrow,title,content in sections)
html=f'''<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Explicación fenomenológica y auditoría del modelo predictivo-prescriptivo ganador v11 de Lingo Smelter, organizada en diez pasos."><title>Del baño a la decisión · Modelo ganador v11 · Lingo Smelter</title><style>{CSS}</style></head><body><a class="skip" href="#contenido">Saltar al contenido</a><nav aria-label="Índice del informe"><div class="brand">Lingo Smelter · Cuaderno técnico</div><h2>Del baño<br>a la decisión</h2><div class="links">{nav}</div><div class="tools"><button id="print">Imprimir / PDF</button><button id="density" aria-pressed="false">Lectura compacta</button></div></nav><div class="progress" aria-hidden="true"></div><main id="contenido"><header><div class="eyebrow">Pirometalurgia → datos → modelo → recomendación</div><h1>Entender el horno.<br>Explicar el ganador.</h1><div class="hero-line"></div><p class="subtitle">Una lectura profunda del enfoque predictivo y prescriptivo v11, desde la selectividad Sn–Fe hasta los límites de la evidencia y su uso en planta.</p><p class="meta">Informe técnico didáctico · 17 septiembre 2026 · Diez pasos de ciencia de datos<br>Basado en código, datos locales y resultados documentados · Lectura e impresión sin conexión</p></header>{body}<footer>Generado por generar_explicacion_ganador.py · Documento explicativo. No modifica modelos ni consignas de planta.</footer></main><script>{JS}</script></body></html>'''
output=ROOT/'MODELO_GANADOR_EXPLICACION_PIROMETALURGICA.html'
output.write_text(html,encoding='utf-8')
print(json.dumps({'archivo':str(output),'bytes':output.stat().st_size,'secciones':len(sections)},ensure_ascii=False))
